fn frame(t: i32) {
    let w: i32 = host::display::width();
    let bx: i32 = w / 2 - 60;
    let by: i32 = 80;
    let down: i32 = host::display::pointer_down();
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let inside: i32 = if px >= bx && px < bx + 120 && py >= by && py < by + 48 { 1 } else { 0 };
    let held: i32 = if down == 1 && inside == 1 { 1 } else { 0 };
    let prev: i32 = host::display::state_get(0);
    let mut fires: i32 = host::display::state_get(1);
    if held == 0 && prev == 1 {
        fires = fires + 1;
        host::display::state_set(1, fires);
    }
    host::display::state_set(0, held);
    host::display::clear(0x101010);
    if held == 1 {
        host::display::fill_rect(bx + 3, by + 3, 120, 48, 0x224466);
        host::display::draw_string(bx + 24, by + 23, "HOLDING", 0x00ff88, 1);
    } else {
        host::display::fill_rect(bx, by, 120, 48, 0x3060a0);
        host::display::draw_string(bx + 30, by + 20, "PRESS", 0xffffff, 1);
    }
    host::display::draw_string(8, 8, "RELEASES", 0x808080, 1);
    host::display::draw_number(80, 8, fires, 0xffffff, 2);
    host::display::present();
}
